import {makeProductSlug} from './ui/product-address.js';
import {loadEmailSettings,renderEmailSettings} from './ui/email-settings.js';
import {renderEditorialEditor} from './ui/editorial-editor.js';
import {AdminPreview} from './ui/admin-preview.js?v=brands3rows1';
import {isConfigured,signIn,signOut,listRows,saveRow,uploadImage,request,checkAdminConnection} from './data/supabase.js';
import {AdminGallery} from './ui/admin-gallery.js?v=crop1';
import {contentFields,loadContent,saveContent} from './data/content.js';
import {renderBrandManager} from './ui/admin-brands.js?v=preview1';
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let productPreview=null,workspacePreview=null,disposeEditorial=null;
const gallery=new AdminGallery($('#photo-gallery'),()=>{dirty=true;updateProductPreview();});
let draftId=null;
let rows=[],editing=null,tab='products',busy=false,dirty=false,generation=0;
const message=text=>{$('#message').textContent=text;};
const error=e=>message(e.message || 'Не удалось выполнить операцию.');
function resetWorkspace(){disposeEditorial?.();disposeEditorial=null;productPreview?.dispose();productPreview=null;workspacePreview?.dispose();workspacePreview=null;gallery.reset();dirty=false;generation++;rows=[];editing=null;$('#workspace-body').replaceChildren();$('#workspace').hidden=true;$('#login-panel').hidden=false;$('#logout').hidden=true;$('#editor').close();$('#product-form').reset();}
let connectionReady=false;
async function checkConnection(){
 const status=$('#connection-status'),button=$('#check-connection'),login=$('#login button');
 button.disabled=true;login.disabled=true;connectionReady=false;status.textContent='Проверяем подключение…';
 const result=isConfigured()?await checkAdminConnection():{ready:false,reason:'version'};
 connectionReady=result.ready;
 const descriptions={ready:'База доступна. Можно войти.',version:'Обновление админки ещё не установлено на сервере.',auth:'Каталог доступен, но служба входа временно недоступна.',backend:'Нет соединения с базой Татнет.',network:'Не удалось связаться с сервером сайта.'};
 status.textContent=descriptions[result.reason]||descriptions.backend;status.dataset.state=result.ready?'ready':'error';
 button.disabled=false;login.disabled=!connectionReady;
}
$('#check-connection').onclick=checkConnection;
checkConnection();
$('#login').addEventListener('submit',async e=>{e.preventDefault();if(!connectionReady)return;const button=e.currentTarget.querySelector('button');button.disabled=true;message('Входим…');const data=new FormData(e.currentTarget);try{await signIn(String(data.get('email')).trim(),data.get('password'));e.target.reset();$('#login-panel').hidden=true;$('#workspace').hidden=false;$('#logout').hidden=false;await showTab('products');}catch(err){e.target.elements.password.value='';error(err);}finally{button.disabled=!connectionReady;}});
$('#logout').onclick=async()=>{if(busy)return;if(dirty&&!confirm('Выйти без сохранения изменений?'))return;try{await signOut();}catch{}finally{resetWorkspace();message('Вы вышли из аккаунта.');}};
document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{if(busy)return;if(dirty&&!confirm('Перейти без сохранения изменений?'))return;dirty=false;showTab(button.dataset.tab);});
async function showTab(next){disposeEditorial?.();disposeEditorial=null;workspacePreview?.dispose();workspacePreview=null;const current=++generation;tab=next;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===tab)));$('#workspace-body').innerHTML='<p>Загрузка…</p>';message('');try{if(tab==='products'){const loaded=await listRows(true);if(current!==generation)return;rows=loaded;renderProducts();}else if(tab==='brands'){const [content,products]=await Promise.all([loadContent(),listRows(true)]);if(current!==generation)return;$('#workspace-body').innerHTML='<div class="admin-preview-layout"><div id="brands-editor-pane" class="admin-edit-pane"></div><div id="brands-preview-host" class="admin-preview-host"></div></div>';workspacePreview=new AdminPreview($('#brands-preview-host'));renderBrandManager($('#brands-editor-pane'),content,products,{onPreview:(entries,publishedProducts,changed)=>workspacePreview?.updateBrands(entries,publishedProducts,changed),message,setDirty:value=>dirty=value,setBusy:value=>{busy=value;$('#logout').disabled=value;document.querySelectorAll('[data-tab]').forEach(b=>b.disabled=value);}});}else if(tab==='email'){let data;try{data=await loadEmailSettings();}catch{if(current!==generation)return;$('#workspace-body').innerHTML='<h1>Уведомления на email</h1><div class="panel"><p>Почтовый модуль ещё не подключён к базе.</p><p>После подключения серверной части здесь можно будет менять адрес. Сейчас заявки продолжают поступать в раздел «Заявки».</p></div>';return;}if(current!==generation)return;renderEmailSettings($('#workspace-body'),data,{onDirty:value=>dirty=value,onBusy:value=>{busy=value;$('#logout').disabled=value;document.querySelectorAll('[data-tab]').forEach(b=>b.disabled=value);},message});}else if(tab==='bookings'){const bookings=await request('/rest/v1/optika_bookings?select=*&order=created_at.desc&limit=500',{authenticated:true});if(current!==generation)return;renderBookings(bookings);}else{const content=await loadContent();if(current!==generation)return;renderContent(content);}}catch(e){if(current===generation){$('#workspace-body').innerHTML='<button id="retry">Повторить загрузку</button>';$('#retry').onclick=()=>showTab(tab);error(e);}}}
function renderProducts(){
 $('#workspace-body').innerHTML='<div class="heading"><div><h1>Коллекция</h1><p class="count">'+rows.length+' товаров · изменения сохраняются в каталоге</p></div><button class="primary" id="new-product">Добавить товар</button></div><div class="toolbar"><input id="product-search" type="search" placeholder="Найти бренд или модель" aria-label="Поиск товаров"><button id="refresh">Обновить</button></div><div id="product-list"></div>';
 $('#new-product').onclick=()=>editProduct(null);$('#refresh').onclick=()=>showTab('products');$('#product-search').oninput=renderList;renderList();
}
function renderList(){const q=$('#product-search').value.toLocaleLowerCase('ru');const filtered=rows.filter(r=>`${r.data.brand} ${r.data.model}`.toLocaleLowerCase('ru').includes(q));$('#product-list').innerHTML=filtered.length?'<div class="table-wrap"><table><thead><tr><th>Фото</th><th>Модель</th><th>Цена</th><th>Видимость</th><th>Действие</th></tr></thead><tbody>'+filtered.map(r=>`<tr><td><div class="admin-product-thumb"><img loading="lazy" src="${esc(r.data.images?.[0]?.src||'')}" alt="${esc(r.data.images?.[0]?.alt||r.data.model)}"><span hidden>Нет фото</span></div></td><td><strong>${esc(r.data.brand)}</strong>${esc(r.data.model)}</td><td>${Number(r.data.price).toLocaleString('ru-RU')} ₽</td><td><span class="badge">${r.published?'В каталоге':'Скрыт'}</span></td><td><div class="catalog-actions"><button data-edit="${esc(r.id)}">Изменить</button><button class="${r.published?'remove-catalog':''}" data-publication="${esc(r.id)}">${r.published?'Убрать из каталога':'Вернуть в каталог'}</button></div></td></tr>`).join('')+'</tbody></table></div>':'<p class="empty">Товары не найдены. Добавьте первую модель.</p>';document.querySelectorAll('.admin-product-thumb img').forEach(img=>{img.onerror=()=>{img.hidden=true;img.nextElementSibling.hidden=false;};if(img.complete&&!img.naturalWidth)img.onerror();});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editProduct(rows.find(r=>r.id===b.dataset.edit)));document.querySelectorAll('[data-publication]').forEach(b=>b.onclick=()=>changePublication(b.dataset.publication));}
async function changePublication(id){
 if(busy)return;const row=rows.find(item=>item.id===id);if(!row)return;
 if(row.published&&!confirm(`Убрать «${row.data.brand} ${row.data.model}» из каталога? Товар останется в админке, и его можно будет вернуть.`))return;
 busy=true;document.querySelectorAll('[data-publication],[data-edit],#new-product,#refresh,[data-tab],#logout').forEach(button=>button.disabled=true);
 try{const saved=await saveRow({...row,published:!row.published},row.updated_at);rows[rows.indexOf(row)]=saved;renderList();message(saved.published?'Товар возвращён в каталог.':'Товар убран из каталога. Его можно вернуть кнопкой в списке.');}
 catch(e){error(e);}
 finally{busy=false;document.querySelectorAll('[data-publication],[data-edit],#new-product,#refresh,[data-tab],#logout').forEach(button=>button.disabled=false);}
}
const field=name=>$('#product-form').elements.namedItem(name);
function editProduct(row){editing=row;draftId=row?.id||crypto.randomUUID();dirty=false;$('#product-form').reset();$('#editor-message').textContent='';$('#editor-title').textContent=row?'Редактирование товара':'Новый товар';const p=row?.data||{};for(const key of ['brand','model','category','gender','price','oldPrice','shortDescription','description','popularity'])if(p[key]!=null)field(key).value=p[key];gallery.reset(p.images||[]);for(const key of ['isFeatured','isNew','isMock'])field(key).checked=!!p[key];field('published').checked=!!row?.published;for(const [key,label] of [['shape','Форма'],['color','Цвет'],['material','Материал оправы']])field(key).value=p.attributes?.[label]||'';$('#editor').showModal();productPreview ||= new AdminPreview($('#product-preview-host'),{product:true});updateProductPreview();}
function currentProductSlug(){return editing?.slug||makeProductSlug(field('brand').value.trim(),field('model').value.trim(),draftId);}
function updateProductPreview(){
 if(!productPreview||!$('#editor').open)return;
 const value=k=>field(k).value.trim();
 const product={...editing?.data,id:editing?.id,slug:currentProductSlug(),brand:value('brand'),model:value('model'),category:value('category'),gender:value('gender'),price:Number(value('price')),oldPrice:value('oldPrice')?Number(value('oldPrice')):null,shortDescription:value('shortDescription'),description:value('description'),isFeatured:field('isFeatured').checked,isNew:field('isNew').checked,isMock:field('isMock').checked,popularity:Number(value('popularity')),images:gallery.items.map(item=>({...item.image,src:item.preview||item.image.src,alt:item.image.alt||value('model')})),attributes:{...editing?.data.attributes,'Форма':value('shape'),'Цвет':value('color'),'Материал оправы':value('material')}};
 productPreview.updateProduct(product,{published:field('published').checked,dirty});
}
function closeEditor(){if(busy)return;if(dirty&&!confirm('Закрыть без сохранения изменений?'))return;dirty=false;productPreview?.clear();gallery.reset();$('#editor').close();}
$('#close-editor').onclick=closeEditor;$('#cancel-editor').onclick=closeEditor;$('#editor').addEventListener('cancel',e=>{e.preventDefault();closeEditor();});$('#product-form').addEventListener('input',()=>{dirty=true;updateProductPreview();});$('#product-form').addEventListener('change',()=>{dirty=true;updateProductPreview();});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
function setBusy(value){busy=value;$('#logout').disabled=value;$('#product-form').querySelectorAll('button,input,textarea,select').forEach(el=>el.disabled=value);gallery.setBusy(value);}
$('#upload').onchange=e=>{try{gallery.addFiles(Array.from(e.target.files));$('#editor-message').textContent='Фотографии добавлены. Выберите главную и сохраните товар.';}catch(e){$('#editor-message').textContent=e.message;}finally{$('#upload').value='';}};
$('#replace-photo').onchange=e=>{try{if(e.target.files[0]){gallery.replaceFile(e.target.files[0]);$('#editor-message').textContent='Фотография заменена. Сохраните товар.';}}catch(e){$('#editor-message').textContent=e.message;}finally{$('#replace-photo').value='';}};
$('#add-photo-url').onclick=()=>{try{gallery.addURL($('#photo-url').value.trim());$('#photo-url').value='';$('#editor-message').textContent='Фотография добавлена. Сохраните товар.';}catch(e){$('#editor-message').textContent=e.message;}};
$('#product-form').onsubmit=async e=>{e.preventDefault();if(busy||!e.target.reportValidity())return;if(gallery.cropping){$('#editor-message').textContent='Завершите обрезку фотографии перед сохранением.';return;}const d=new FormData(e.target),value=k=>String(d.get(k)||'').trim();if(!gallery.items.length){$('#editor-message').textContent='Добавьте хотя бы одну фотографию.';return;}if(value('oldPrice')&&Number(value('oldPrice'))<=Number(value('price'))){$('#editor-message').textContent='Старая цена должна быть больше текущей.';return;}
 const data={...editing?.data,brand:value('brand'),model:value('model'),category:value('category'),gender:value('gender'),price:Number(value('price')),oldPrice:value('oldPrice')?Number(value('oldPrice')):null,shortDescription:value('shortDescription'),description:value('description'),popularity:Number(value('popularity')),isFeatured:d.has('isFeatured'),isNew:d.has('isNew'),isMock:d.has('isMock'),images:[],attributes:{...editing?.data.attributes,'Форма':value('shape'),'Цвет':value('color'),'Материал оправы':value('material')}};
 setBusy(true);$('#editor-message').textContent='Сохраняем…';try{data.images=await gallery.prepare(uploadImage,text=>{$('#editor-message').textContent=text;},`${value('brand')} ${value('model')}`);$('#editor-message').textContent='Сохраняем товар…';await saveRow({id:editing?.id||draftId,slug:currentProductSlug(),published:d.has('published'),data},editing?.updated_at);dirty=false;productPreview?.clear();gallery.reset();$('#editor').close();await showTab('products');message('Товар сохранён. Витрина обновится при следующем открытии.');}catch(e){$('#editor-message').textContent=e.message;}finally{setBusy(false);}};
function renderBookings(bookings){$('#workspace-body').innerHTML='<div class="heading"><div><h1>Заявки</h1><p class="count">Последние 500 заявок · '+bookings.filter(b=>b.status==='new').length+' новых</p></div><button id="refresh">Обновить</button></div>'+(bookings.length?'<div class="table-wrap"><table><thead><tr><th>Дата</th><th>Имя</th><th>Телефон</th><th>Обращение</th><th>Статус</th></tr></thead><tbody>'+bookings.map(b=>`<tr><td>${esc(new Date(b.created_at).toLocaleString('ru-RU'))}</td><td>${esc(b.name)}</td><td><a href="tel:${esc(b.phone)}">${esc(b.phone)}</a></td><td>${b.kind==='fitting'?'Примерка':'Проверка зрения'}${b.kind==='fitting'?'<p>'+esc(b.product_label||'')+'</p>':''}</td><td><select class="status-select" aria-label="Статус заявки ${esc(b.name)}" data-status="${esc(b.id)}" data-current="${esc(b.status)}">${[['new','Новая'],['contacted','Связались'],['closed','Закрыта']].map(([value,label])=>`<option value="${value}" ${b.status===value?'selected':''}>${label}</option>`).join('')}</select></td></tr>`).join('')+'</tbody></table></div>':'<p class="empty panel">Заявок пока нет.</p>');$('#refresh').onclick=()=>showTab('bookings');document.querySelectorAll('[data-status]').forEach(select=>select.onchange=async()=>{select.disabled=true;try{const result=await request(`/rest/v1/optika_bookings?id=eq.${encodeURIComponent(select.dataset.status)}&status=eq.${encodeURIComponent(select.dataset.current)}`,{method:'PATCH',authenticated:true,body:{status:select.value},headers:{Prefer:'return=representation'}});if(!result.length)throw new Error('Статус уже изменён. Обновите список.');select.dataset.current=select.value;message('Статус заявки сохранён.');}catch(e){select.value=select.dataset.current;error(e);}finally{select.disabled=false;}});}
function renderContent(row){
 $('#workspace-body').innerHTML='<div class="admin-preview-layout"><div class="admin-edit-pane" id="editorial-pane"></div><div id="content-preview-host" class="admin-preview-host"></div></div>';
 workspacePreview=new AdminPreview($('#content-preview-host'));
 disposeEditorial=renderEditorialEditor($('#editorial-pane'),row,{about:tab==='about',promotions:tab==='promotions',preview:workspacePreview,onDirty:value=>dirty=value,onBusy:value=>{busy=value;$('#logout').disabled=value;document.querySelectorAll('[data-tab]').forEach(button=>button.disabled=value);},message});
}

